import{_ as e,o as a,c as i,a2 as l}from"./chunks/framework.BXzK3EA4.js";const c=JSON.parse('{"title":"경제와 생산, 물류 규칙","description":"","frontmatter":{},"headers":[],"relativePath":"rules/Rules-EconomyLogistics.md","filePath":"rules/Rules-EconomyLogistics.md"}'),r={name:"rules/Rules-EconomyLogistics.md"};function d(n,t,h,o,g,s){return a(),i("div",null,[...t[0]||(t[0]=[l('<h1 id="경제와-생산-물류-규칙" tabindex="-1">경제와 생산, 물류 규칙 <a class="header-anchor" href="#경제와-생산-물류-규칙" aria-label="Permalink to &quot;경제와 생산, 물류 규칙&quot;">​</a></h1><blockquote><p>출처: docs/game-logic/Economy-and-Production.md, docs/game-logic/Logistics-and-Infrastructure.md — 계약 수치는 구현 상수를 우선한다.</p></blockquote><h2 id="개요" tabindex="-1">개요 <a class="header-anchor" href="#개요" aria-label="Permalink to &quot;개요&quot;">​</a></h2><p>경제는 생존 자원과 제작 자원과 노동과 전력과 실제 운송 능력을 한 장부로 묶는다.</p><p>물류는 창고의 존재 사실이 아니라 필요한 종류의 물자가 허가된 경로로 제때 도착하는 능력이다.</p><p>수치는 설계 가정이므로 구현 상수가 있으면 그 값을 우선한다.</p><h2 id="핵심-수치" tabindex="-1">핵심 수치 <a class="header-anchor" href="#핵심-수치" aria-label="Permalink to &quot;핵심 수치&quot;">​</a></h2><table tabindex="0"><thead><tr><th>항목</th><th style="text-align:right;">값</th><th style="text-align:right;">최소</th><th style="text-align:right;">최대</th></tr></thead><tbody><tr><td>정상 매수·매도 반폭</td><td style="text-align:right;">10%</td><td style="text-align:right;">5%</td><td style="text-align:right;">35%</td></tr><tr><td>고립 추가 반폭</td><td style="text-align:right;">0~10%</td><td style="text-align:right;">0%</td><td style="text-align:right;">10%</td></tr><tr><td>가격 격리 민감도</td><td style="text-align:right;">0.35</td><td style="text-align:right;">0</td><td style="text-align:right;">1</td></tr><tr><td>물 부족 노동 감점 계수</td><td style="text-align:right;">0.70</td><td style="text-align:right;">0</td><td style="text-align:right;">1</td></tr><tr><td>식량 부족 노동 감점 계수</td><td style="text-align:right;">0.50</td><td style="text-align:right;">0</td><td style="text-align:right;">1</td></tr><tr><td>전력 부족 노동 감점 계수</td><td style="text-align:right;">0.30</td><td style="text-align:right;">0</td><td style="text-align:right;">1</td></tr><tr><td>최저 노동 지속성</td><td style="text-align:right;">20%</td><td style="text-align:right;">0%</td><td style="text-align:right;">100%</td></tr><tr><td>노동 지속성 공식 하한</td><td style="text-align:right;">0.2</td><td style="text-align:right;">0.2</td><td style="text-align:right;">1</td></tr><tr><td>역당 행정 수요</td><td style="text-align:right;">1점</td><td style="text-align:right;">0.5</td><td style="text-align:right;">3</td></tr><tr><td>운영 노선당 조율 수요</td><td style="text-align:right;">0.5점</td><td style="text-align:right;"></td><td style="text-align:right;"></td></tr><tr><td>배정 물류 조율 공급</td><td style="text-align:right;">2점</td><td style="text-align:right;"></td><td style="text-align:right;"></td></tr><tr><td>연락 조율 공급</td><td style="text-align:right;">1.5점</td><td style="text-align:right;"></td><td style="text-align:right;"></td></tr><tr><td>기록 조율 공급</td><td style="text-align:right;">1.5점</td><td style="text-align:right;"></td><td style="text-align:right;"></td></tr><tr><td>과확장 시 노선 산출 감소 상한</td><td style="text-align:right;">50%</td><td style="text-align:right;"></td><td style="text-align:right;">50%</td></tr><tr><td>과확장 시 현지 산출 감소 상한</td><td style="text-align:right;">25%</td><td style="text-align:right;"></td><td style="text-align:right;">25%</td></tr><tr><td>연결 처리량</td><td style="text-align:right;">0~1</td><td style="text-align:right;">0</td><td style="text-align:right;">1</td></tr><tr><td>시설 상태 I</td><td style="text-align:right;">1</td><td style="text-align:right;">0</td><td style="text-align:right;">1</td></tr><tr><td>전력 P</td><td style="text-align:right;">0~1</td><td style="text-align:right;">0</td><td style="text-align:right;">1</td></tr><tr><td>접근권 X</td><td style="text-align:right;">0~1</td><td style="text-align:right;">0</td><td style="text-align:right;">1</td></tr><tr><td>위험 H</td><td style="text-align:right;">0~1</td><td style="text-align:right;">0</td><td style="text-align:right;">1</td></tr><tr><td>일반 허브 유지비</td><td style="text-align:right;">5 보급점/일</td><td style="text-align:right;">0</td><td style="text-align:right;">20</td></tr><tr><td>허브 노동</td><td style="text-align:right;">1교대/일</td><td style="text-align:right;">0</td><td style="text-align:right;">4</td></tr><tr><td>원정대 피로</td><td style="text-align:right;">0</td><td style="text-align:right;">0</td><td style="text-align:right;">100</td></tr><tr><td>원정대 준비도</td><td style="text-align:right;">100</td><td style="text-align:right;">0</td><td style="text-align:right;">100</td></tr><tr><td>과확장</td><td style="text-align:right;">지속 0 / 노출 0~1 / 심각 1~2</td><td style="text-align:right;">0</td><td style="text-align:right;">2</td></tr><tr><td>고립 단계</td><td style="text-align:right;">정상 0 / 부분 봉쇄 1 / 완전 차단 2</td><td style="text-align:right;">0</td><td style="text-align:right;">2</td></tr><tr><td>부하</td><td style="text-align:right;">준비 0~24 / 긴장 25~49 / 임계 50~74 / 실패 75~99 / 붕괴 100</td><td style="text-align:right;">0</td><td style="text-align:right;">100</td></tr><tr><td>부족 부하 계수</td><td style="text-align:right;">20</td><td style="text-align:right;"></td><td style="text-align:right;"></td></tr><tr><td>완전고립 부하 계수</td><td style="text-align:right;">8</td><td style="text-align:right;"></td><td style="text-align:right;"></td></tr><tr><td>과확장 부하 계수</td><td style="text-align:right;">6</td><td style="text-align:right;"></td><td style="text-align:right;"></td></tr><tr><td>부하Δ</td><td style="text-align:right;">0~35</td><td style="text-align:right;">0</td><td style="text-align:right;">35</td></tr><tr><td>감시기간 부하 회복</td><td style="text-align:right;">15</td><td style="text-align:right;"></td><td style="text-align:right;"></td></tr><tr><td>부담비율 분모 0·분자 양수</td><td style="text-align:right;">3</td><td style="text-align:right;"></td><td style="text-align:right;"></td></tr><tr><td>구간 최소 이동시간</td><td style="text-align:right;">0.25시간</td><td style="text-align:right;">0.25</td><td style="text-align:right;">24</td></tr></tbody></table><h2 id="조항" tabindex="-1">조항 <a class="header-anchor" href="#조항" aria-label="Permalink to &quot;조항&quot;">​</a></h2><h3 id="recon-01-필수-소비-선예약" tabindex="-1">RECON-01 필수 소비 선예약 <a class="header-anchor" href="#recon-01-필수-소비-선예약" aria-label="Permalink to &quot;RECON-01 필수 소비 선예약&quot;">​</a></h3><p>하루가 열리면 주민용 물과 식량과 응급 의료를 먼저 예약한다.</p><p>시설 입력은 이 예약을 소비하지 않는다.</p><p>시장 주문은 그 다음 순위에 둔다.</p><h3 id="recon-02-생산-병목" tabindex="-1">RECON-02 생산 병목 <a class="header-anchor" href="#recon-02-생산-병목" aria-label="Permalink to &quot;RECON-02 생산 병목&quot;">​</a></h3><p>생산량은 기본산출에 노동률과 입력률과 전력률의 최솟값과 시설상태를 곱한 값이다.</p><p>요구량이 0이거나 필요 입력 집합이 비어 있으면 그 충족률은 1이다.</p><p>필요 노동 10교대 중 8교대 입력 70% 전력 90% 시설 상태 80% 기본산출 100이면 생산량은 56이다.</p><h3 id="recon-03-영-분모-금지" tabindex="-1">RECON-03 영 분모 금지 <a class="header-anchor" href="#recon-03-영-분모-금지" aria-label="Permalink to &quot;RECON-03 영 분모 금지&quot;">​</a></h3><p>어떤 경우에도 0으로 나누지 않는다.</p><p>수요가 0이면 부족률은 0이다.</p><p>필요 노동이나 필요 전력이 0이면 해당 률은 1이다.</p><h3 id="recon-04-일일-정산-고정" tabindex="-1">RECON-04 일일 정산 고정 <a class="header-anchor" href="#recon-04-일일-정산-고정" aria-label="Permalink to &quot;RECON-04 일일 정산 고정&quot;">​</a></h3><p>일일 정산 순서는 결정론의 일부다.</p><p>당일 노선 상태와 통과권과 부대 위치와 가용 인력과 정책과 수요와 지정 우선순위를 먼저 고정한다.</p><p>주간 시스템은 하루를 다시 계산하지 않는다.</p><h3 id="recon-05-동점-절단" tabindex="-1">RECON-05 동점 절단 <a class="header-anchor" href="#recon-05-동점-절단" aria-label="Permalink to &quot;RECON-05 동점 절단&quot;">​</a></h3><p>남은 인력은 지정 우선순위로 시설에 배정한다.</p><p>동순위는 안정 시설 ID 다음 안정 인력 ID로 끊는다.</p><p>미예약 전력과 재고 입력도 같은 규칙을 쓴다.</p><h3 id="recon-06-화물-발송과-도착" tabindex="-1">RECON-06 화물 발송과 도착 <a class="header-anchor" href="#recon-06-화물-발송과-도착" aria-label="Permalink to &quot;RECON-06 화물 발송과 도착&quot;">​</a></h3><p>미예약 출발 재고에서 인가 화물을 발송한다.</p><p>한도는 도착지 여유 저장과 화물 노동과 노선 용량과 통과권이다.</p><p>도착 재고는 도착지의 당일 필수 소비에 쓸 수 있다.</p><h3 id="recon-07-가격과-격리-민감도" tabindex="-1">RECON-07 가격과 격리 민감도 <a class="header-anchor" href="#recon-07-가격과-격리-민감도" aria-label="Permalink to &quot;RECON-07 가격과 격리 민감도&quot;">​</a></h3><p>가격은 재고를 만들지 않는다.</p><p>실제 물건과 구매력과 접근권과 운송 용량이 있어야 거래가 성립한다.</p><p>격리 민감도는 0.35다.</p><h3 id="recon-08-격리의-범위" tabindex="-1">RECON-08 격리의 범위 <a class="header-anchor" href="#recon-08-격리의-범위" aria-label="Permalink to &quot;RECON-08 격리의 범위&quot;">​</a></h3><p>격리는 생산을 직접 지우지 않는다.</p><p>수송을 제한하고 가격 반폭을 넓히며 수입 의존도가 0보다 큰 자원의 가격만 올린다.</p><p>고립된 자급 역은 해당 자원의 가격에 임의의 고립 감점을 받지 않는다.</p><h3 id="recon-09-노동-지속성" tabindex="-1">RECON-09 노동 지속성 <a class="header-anchor" href="#recon-09-노동-지속성" aria-label="Permalink to &quot;RECON-09 노동 지속성&quot;">​</a></h3><p>노동 지속성은 1에서 자원별 감점계수와 부족률의 곱의 합을 뺀 값을 0.2 이상 1 이하로 자른다.</p><p>물 감점 계수는 0.70이고 식량 0.50이고 전력 0.30이다.</p><p>물 수요 100 중 50만 충족되고 식량과 전력이 충족되면 노동 지속성은 0.65다.</p><h3 id="recon-10-부족의-대상" tabindex="-1">RECON-10 부족의 대상 <a class="header-anchor" href="#recon-10-부족의-대상" aria-label="Permalink to &quot;RECON-10 부족의 대상&quot;">​</a></h3><p>물과 식량과 전력 부족은 다음 날 노동을 낮춘다.</p><p>의약품 부족은 치료 행동 자체를 제한한다.</p><p>탄약 부족은 전술 장비와 출격 가능 수량만 제한한다.</p><h3 id="recon-11-직능-대체-금지" tabindex="-1">RECON-11 직능 대체 금지 <a class="header-anchor" href="#recon-11-직능-대체-금지" aria-label="Permalink to &quot;RECON-11 직능 대체 금지&quot;">​</a></h3><p>인력 부족 시 자격 없는 인물을 자동 대체하지 않는다.</p><p>생산 주문은 부분 완료된다.</p><h3 id="recon-12-과확장-산출-감점" tabindex="-1">RECON-12 과확장 산출 감점 <a class="header-anchor" href="#recon-12-과확장-산출-감점" aria-label="Permalink to &quot;RECON-12 과확장 산출 감점&quot;">​</a></h3><p>과확장 시 노선 산출은 최대 50%까지 감소한다.</p><p>현지 산출은 최대 25%까지 감소한다.</p><p>감소량은 과확장을 0 이상 1 이하로 자른 값에 비례하고 그 상한을 넘지 않는다.</p><h3 id="recon-13-조율-수요와-공급" tabindex="-1">RECON-13 조율 수요와 공급 <a class="header-anchor" href="#recon-13-조율-수요와-공급" aria-label="Permalink to &quot;RECON-13 조율 수요와 공급&quot;">​</a></h3><p>조율 수요는 역당 행정 수요 1점에 운영 노선당 0.5점을 더한 값이다.</p><p>조율 공급은 배정 물류 2점과 연락 1.5점과 기록 1.5점과 저작 업그레이드다.</p><p>이 둘은 과확장 공식의 통치부담과 행정역량 입력이다.</p><h3 id="recon-14-구간-처리량" tabindex="-1">RECON-14 구간 처리량 <a class="header-anchor" href="#recon-14-구간-처리량" aria-label="Permalink to &quot;RECON-14 구간 처리량&quot;">​</a></h3><p>실제 처리량 C_e는 B_e와 시설상태 I_e와 전력 P_e와 접근권 X_e와 (1-H_e)를 곱한 뒤 0 이상 B_e 이하로 자른다.</p><p>I와 P와 X와 H의 범위는 0부터 1이고 I의 기본값은 1이다.</p><p>기본 처리량 100에 시설 0.8 전력 0.5 접근권 1 위험 0.1이면 C는 36이다.</p><h3 id="recon-15-과확장-척도" tabindex="-1">RECON-15 과확장 척도 <a class="header-anchor" href="#recon-15-과확장-척도" aria-label="Permalink to &quot;RECON-15 과확장 척도&quot;">​</a></h3><p>과확장은 0 이상 2 이하 공유 척도이며 물류 문서의 정의가 기준이다.</p><p>세 부담비율의 최댓값에서 1을 뺀 값을 0 이상 2 이하로 자른다.</p><p>분모가 0인데 분자가 남으면 그 비율은 3이라 과확장이 즉시 2로 포화한다.</p><h3 id="recon-16-고립-단계" tabindex="-1">RECON-16 고립 단계 <a class="header-anchor" href="#recon-16-고립-단계" aria-label="Permalink to &quot;RECON-16 고립 단계&quot;">​</a></h3><p>고립 단계는 0 이상 2 이하 연속 척도다.</p><p>모든 합법 주 경로가 정상이면 0이고 우회와 경화물만 가능하면 1이고 모든 합법 경로가 차단되면 2다.</p><p>중간값은 봉쇄된 합법 경로 처리량의 비율로 보간한다.</p><h3 id="recon-17-부하-누적" tabindex="-1">RECON-17 부하 누적 <a class="header-anchor" href="#recon-17-부하-누적" aria-label="Permalink to &quot;RECON-17 부하 누적&quot;">​</a></h3><p>부하Δ는 20배 부족률과 8배 완전고립과 6배 과확장을 더한 값을 0 이상 35 이하로 자른다.</p><p>완전고립은 고립 단계가 2이면 1 아니면 0이다.</p><p>부하 A는 기존 값에 부하Δ를 더한 뒤 0 이상 100 이하로 자른다.</p><h3 id="recon-18-부하-회복과-구간" tabindex="-1">RECON-18 부하 회복과 구간 <a class="header-anchor" href="#recon-18-부하-회복과-구간" aria-label="Permalink to &quot;RECON-18 부하 회복과 구간&quot;">​</a></h3><p>보급률이 1이고 허가된 안전 거점에서 필요 능력 태그가 있으면 감시기간당 15만큼 회복한다.</p><p>0~24는 준비 25~49는 긴장 50~74는 임계 75~99는 실패 100은 붕괴다.</p><p>자동 비율 사망은 적용하지 않는다.</p><h3 id="recon-19-부하-구간-효과" tabindex="-1">RECON-19 부하 구간 효과 <a class="header-anchor" href="#recon-19-부하-구간-효과" aria-label="Permalink to &quot;RECON-19 부하 구간 효과&quot;">​</a></h3><p>25~49 긴장은 준비도 감소와 여유 용량이 필요한 임의 행동 제한을 적용한다.</p><p>50~74 임계는 구간 진입 시 미치료 부상 하나 악화 또는 최하위 상태 장비 하나 손상을 확정한다.</p><p>둘 다 없으면 지정 화물을 잃고 대상은 심각도 다음 영속 ID 순이다.</p><h3 id="recon-20-실패와-붕괴" tabindex="-1">RECON-20 실패와 붕괴 <a class="header-anchor" href="#recon-20-실패와-붕괴" aria-label="Permalink to &quot;RECON-20 실패와 붕괴&quot;">​</a></h3><p>75~99 실패는 후퇴와 화물 유기와 현지 조달과 분할과 명시적 고위험 속행 중 결정을 강제한다.</p><p>100 붕괴는 전진 개시를 막고 좌초와 항복과 해산 또는 구조와 최후 조우로 넘긴다.</p><h3 id="recon-21-보급-태그" tabindex="-1">RECON-21 보급 태그 <a class="header-anchor" href="#recon-21-보급-태그" aria-label="Permalink to &quot;RECON-21 보급 태그&quot;">​</a></h3><p>보급 배분은 정책 우선순위와 영속 ID 순서로 결정한다.</p><p>물자는 능력 태그가 맞는 수요에만 충족한다.</p><p>의료와 배터리와 수리 태그는 일반 보급점이 남아 있어도 상호 비대체다.</p><h3 id="recon-22-허브와-봉쇄" tabindex="-1">RECON-22 허브와 봉쇄 <a class="header-anchor" href="#recon-22-허브와-봉쇄" aria-label="Permalink to &quot;RECON-22 허브와 봉쇄&quot;">​</a></h3><p>일반 허브 유지비는 5 보급점/일이고 허브 노동은 1교대/일이다.</p><p>불필요한 중복 허브도 유지비를 내며 최대 흐름과 비축과 단일고장 생존성을 늘리지 않으면 효용 0으로 표시한다.</p><p>봉쇄 연결은 삭제하지 않고 원인과 수리 자원과 예상 시간을 표시한다.</p><h3 id="recon-23-전력-차단과-임시-복구" tabindex="-1">RECON-23 전력 차단과 임시 복구 <a class="header-anchor" href="#recon-23-전력-차단과-임시-복구" aria-label="Permalink to &quot;RECON-23 전력 차단과 임시 복구&quot;">​</a></h3><p>전력 차단 환승역은 양쪽 터널이 멀쩡해도 전동 화물 흐름이 0일 수 있다.</p><p>임시 복구는 기본적으로 도보와 경화물만 통과시킨다.</p><p>중화물과 무장 통과는 별도 승인이다.</p><h3 id="recon-24-영-요구-생산과-영수증" tabindex="-1">RECON-24 영 요구 생산과 영수증 <a class="header-anchor" href="#recon-24-영-요구-생산과-영수증" aria-label="Permalink to &quot;RECON-24 영 요구 생산과 영수증&quot;">​</a></h3><p>필요 노동과 전력과 입력이 모두 0이고 필요 입력 집합이 비어 있으면 시설 상태 80%에서 기본산출 100의 생산량은 80이다.</p><p>원인별 영수증을 남기고 일일 집계를 갱신한다.</p><p>주간 시스템은 이 영수증만 읽는다.</p><h2 id="판정-순서" tabindex="-1">판정 순서 <a class="header-anchor" href="#판정-순서" aria-label="Permalink to &quot;판정 순서&quot;">​</a></h2><ol><li>당일 노선 상태와 통과권과 부대 위치와 가용 인력과 정책과 수요와 지정 우선순위를 고정한다.</li><li>네트워크 과확장과 가용 노선 용량을 계산한다.</li><li>방어와 원정과 치료와 운송 명령에 인력을 예약한다.</li><li>개시 재고와 전력을 당일 필수 소비에 예약한다. 시설 입력은 이 예약을 소비하지 않는다.</li><li>남은 인력을 지정 우선순위로 시설에 배정한다. 동순위는 안정 시설 ID 다음 안정 인력 ID로 끊는다.</li><li>미예약 전력과 재고 입력을 같은 우선순위와 동점 규칙으로 시설에 배정한다.</li><li>배정에 따라 생산을 실행하고 입력을 소비하며 산출을 더한다.</li><li>미예약 출발 재고에서 인가 화물을 발송한다. 도착지 여유 저장과 화물 노동과 노선 용량과 통과권으로 제한한다. 도착 재고는 도착지의 당일 필수 소비에 쓸 수 있다.</li><li>예약분과 도착 화물과 당일 산출로 필수 소비를 같은 소비자 우선순위로 정산한다.</li><li>부족과 다음 날 노동 지속성과 현지 매수·매도 가격과 넘침과 노출된 호송·비축 사실을 계산한다.</li><li>원인별 영수증을 남기고 일일 집계를 갱신한다.</li><li>감시기간 말에 부하Δ를 더하고 0 이상 100 이하로 자른다.</li><li>보급률이 1이고 허가된 안전 거점과 필요 능력 태그가 있으면 증가 대신 15만큼 회복한다.</li><li>부하 구간 효과를 적용한다. 실패는 결정을 강제하고 붕괴는 전진 개시를 막는다.</li></ol><h2 id="금지-사항" tabindex="-1">금지 사항 <a class="header-anchor" href="#금지-사항" aria-label="Permalink to &quot;금지 사항&quot;">​</a></h2><ul><li>0으로 나누는 계산</li><li>가격만으로 재고를 만드는 일</li><li>자격 없는 인물의 자동 대체</li><li>의료·배터리·수리 태그를 일반 보급점으로 대체하는 일</li><li>봉쇄 연결을 삭제하는 일</li><li>자동 비율 사망</li><li>격리가 생산을 직접 지우는 처리</li><li>주간 시스템이 하루를 다시 계산하는 일</li><li>시설 입력이 필수 예약을 소비하는 일</li><li>임시 복구 구간에서 승인 없이 중화물과 무장을 통과시키는 일</li><li>고립 자급 역에 임의의 고립 가격 감점을 매기는 일</li><li>수요 0을 부족 양수로 처리하는 일</li><li>경로가 없어도 비축이 있는데 즉시 굶기는 일</li><li>효용 없는 중복 허브의 유지비를 면제하는 일</li></ul><h2 id="출처" tabindex="-1">출처 <a class="header-anchor" href="#출처" aria-label="Permalink to &quot;출처&quot;">​</a></h2><ul><li><code>docs/game-logic/Economy-and-Production.md</code></li><li><code>docs/game-logic/Logistics-and-Infrastructure.md</code></li></ul><p>표와 공식의 모든 수치는 두 문서의 설계 가정이다.</p><p>계약 또는 잠긴 표기는 원문에 없다.</p><p>노동 지속성 하한 20%와 공식 0.2는 동일 값이다.</p><p>과확장 0~2 정의는 물류 문서가 기준이다.</p><p>경제 문서의 노선 50%·현지 25% 감소는 과확장을 0 이상 1 이하로 자른 값에 비례한다.</p><p>구현 상수가 있으면 그 값을 우선한다.</p>',115)])])}const x=e(r,[["render",d]]);export{c as __pageData,x as default};
